import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Embodied Navigation Foundation Model","description":"","frontmatter":{"title":"Embodied Navigation Foundation Model","arxiv":"2509.12129","date":"2025-09-15","authors":"Jiazhao Zhang, Anqi Li, Yunpeng Qi, Minghan Li, Jiahang Liu, Shaoan Wang, Haoran Liu, Gengze Zhou, Yuze Wu, et al.","categories":"cs.RO","topics":"具身导航, 跨本体基础模型, 多视角 token 组织","outline":[2,2]},"headers":[],"relativePath":"papers/2509.12129.md","filePath":"papers/2509.12129.md","lastUpdated":null}'),e={name:"papers/2509.12129.md"};function l(m,s,r,i,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="embodied-navigation-foundation-model" tabindex="-1">Embodied Navigation Foundation Model <a class="header-anchor" href="#embodied-navigation-foundation-model" aria-label="Permalink to &quot;Embodied Navigation Foundation Model&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2509.12129" target="_blank" rel="noreferrer">2509.12129</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-09-15</td></tr><tr><td><strong>作者</strong></td><td>Jiazhao Zhang, Anqi Li, Yunpeng Qi, Minghan Li, Jiahang Liu, Shaoan Wang, Haoran Liu, Gengze Zhou, Yuze Wu, et al.</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用「时间-视角指示 token」告诉 LLM 每个视觉 token 来自哪个相机、哪个时刻，再用 token 预算约束下的指数采样裁剪历史，把四种本体、四类导航任务压进一个统一的轨迹回归模型（NavFoM）。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv abs 页给出的 HTML 版本是 <strong>v2</strong>（v1 2025-09-15，v2 2025-09-16，内容规模一致），本文按 v2 全文撰写。abs 页元数据摘要写「Extensive evaluations on public benchmarks」，v2 正文写「seven public benchmarks」，以正文为准。作者共 17 位，frontmatter 取前 9 位 + et al.。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>导航被拆成了太多互不相通的小格子：VLN-CE 上跑的是单目 RGB + 深度 + 里程计的室内策略，ObjectNav 上跑的是探索-识别两段式启发式，主动视觉跟踪上跑的是检测器加视觉伺服，自动驾驶上跑的是带车道线与他车状态的规划器。每换一种机器人（四足、无人机、轮式底盘、汽车），相机数量、安装角度、轨迹尺度全都变，模型也要重写。NavFoM 要问的是：这些任务是否本来就是同一个映射的不同实例——「若干路第一视角视频 + 一句话指令 → 接下来一段航点轨迹」？</p><p>这个问题值得问，是因为格子化带来的代价非常具体。每个格子的数据量都上不去（此前最大的导航模型训练样本量在百万级），每个格子的架构都绑死了传感器配置，于是任何一次硬件改动都要重训。如果统一表述成立，导航就能像 VLM 一样吃到跨域数据的规模红利：作者收集了 802 万条导航样本 + 476 万条图文/视频 QA 样本，共 1270 万条，用 56 张 H100 训 72 小时（4032 GPU 小时）一个 epoch，然后在七个公开基准上不做任务特定微调直接评测。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>最相关的三条线各自解决了一半问题。<strong>跨任务导航</strong>这一线，Uni-NaVid 用视频 VLM 把 VLN、ObjectNav、EQA、人类跟随统一成视频指令跟随，证明了跨任务共训有收益；但它假定单一前视相机、限于室内可控环境。<strong>跨本体导航</strong>这一线，GNM/ViNT 这类工作在多机器人数据上训 transformer 策略，隐式学到本体的物理尺寸先验；但它们绑定在特定的目标条件形式（图像目标/位姿目标）上，任务面很窄。<strong>多视角 VLN</strong> 这一线（如把全景切片拼进 token 序列的做法）能吃多相机，但要么把所有视角 token 直接顺序拼接、要么用为特定相机布置手工设计的位置编码，模型无法在训练后接受一个没见过的相机数量。</p><p>为什么「视角与时间信息如何进入 LLM」这件事此前没被当成核心问题？我的判断是：在单相机设定下它根本不构成问题——视觉 token 的顺序天然等于时间顺序，LLM 靠位置编码就能读出来。只有当相机数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 与时间步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 同时可变、且二者的 token 在同一条序列里交错时，「这一段 token 是 3 秒前的左后视角」才成为一个必须显式表达的量。NavFoM 的第一条贡献正是把这件被单相机设定掩盖掉的事显式化。</p><p>另一件被掩盖的事是 token 预算。离线基准上，模型可以把整段历史都喂进去；一旦要在机器人上实时跑，显存和延迟就把序列长度锁死。此前的两种做法各有硬伤：token merging 训练期额外开销大且推理速度随时间波动；均匀采样在长序列上会把最近几帧稀释掉，而最近几帧恰恰是决定下一步动作的部分。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从 2024 年的经验观察出发：视频 VLM 已经能把「一段第一视角视频 + 一句指令 → 下一步离散动作」学得不错（NaVid 系列），且跨任务混训确实涨点。顺着这条线往前推，第一个卡点是离散动作。四足机器人的 <code>FORWARD/LEFT/RIGHT</code> 和无人机的三维位移、汽车的几十米轨迹根本不在同一个动作空间里，想统一就必须换成连续航点。换成航点之后立刻遇到第二个问题：室内一步 0.25 米，汽车一步几十米，直接回归会让波动最大的那个域主导损失。一个朴素但有效的处置是按任务给一个缩放因子把所有维度归一化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，并且用 99 分位而非最大值来定这个因子以避开离群轨迹。</p><p>第三个卡点是相机。既然要跨本体，就不能假设相机数固定。这时可以借用 LLM 社区已经验证过的经验：给不同模态/任务加专用的特殊 token 比改动视觉 token 本身更稳。于是「不要动视觉 token 的表示空间，只在它前面插一个携带 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϕ</span><span class="mclose">)</span></span></span></span> 的指示 token」就是一个自然的选择。要让这个 token 有用，它必须满足三件事——方位角的圆周连续性（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≡</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span>）、时间的唯一可辨性、以及可以按任务选择性地关掉（图像 QA 没有时间也没有视角）。把这三条写下来，正弦编码 + 两个 MLP + 一个可学 base 的三段式结构几乎是被逼出来的。</p><p>最后一个卡点是部署。要在 4090 上 0.5 秒内出 8 个航点，就得给 token 数一个硬上限。既然上限是硬的，采样概率就应该是「在满足期望 token 数不超预算的前提下，尽量偏向近期」——这正好对应一条带下界的指数遗忘曲线，其衰减率可以离线用 Brent 法解出来。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>导航模型的困难不在于视觉编码，而在于<strong>告诉 LLM 每个视觉 token 的时空坐标</strong>：只要 LLM 知道「这 4 个 token 来自 3 秒前的右后相机」，它就能自己把多视角、变长历史组织成可用的上下文，而不需要为每种相机配置写一套架构。第二个直觉是：历史帧不必等价——把最近一帧留成 64 个 token 的细粒度，把历史压成每帧 4 个 token 并按一条遗忘曲线随机丢弃，就能在固定 token 预算下同时保住「看清现在」和「记得过去」。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 VLN-CE RxR 的四相机设定为例走一遍。</p><ol><li><strong>观测编码</strong>：第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 步拿到 4 路 RGB。DINOv2 与 SigLIP 分别抽特征后沿通道拼接，得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">576</span></span></span></span> 个 patch 的特征。对最新一帧做网格池化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span> 个 token（细粒度），对全部历史帧池化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 个 token（粗粒度），再过两层 MLP 投影到 LLM 空间。</li><li><strong>TVI token</strong>：对每一帧、每一路相机，生成一个指示 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">TVI</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Base</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">time</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord text"><span class="mord">TimePE</span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">))</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">angle</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord text"><span class="mord">AnglePE</span></span><span class="mopen">(</span><span class="mord mathnormal">ϕ</span><span class="mclose">))</span></span></span></span>，插在该帧视觉 token 之前。图像 QA 只用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Base</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，视频 QA 只加时间项。作者把 TVI token 做 UMAP 降维后可以看到它们按方位角与时间步分层聚类。</li><li><strong>BATS 采样</strong>：给定 token 预算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2048</span></span></span></span>，先算出允许的期望帧数，再解出指数衰减率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 对历史帧做伯努利采样。</li><li><strong>LLM 前向与轨迹解码</strong>：采样后的视觉 token 与指令 token 拼接送入 Qwen2-7B，取动作隐状态过三层 MLP 得到 8 个归一化航点，乘以任务缩放因子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0037em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">task</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 还原成米制。轮式/汽车用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span></span></span></span>，无人机用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mclose">)</span></span></span></span>。</li><li><strong>训练</strong>：导航用 MSE，QA 用交叉熵，总损失 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">nav</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">QA</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span>。为了避免每步在线编码上百帧，粗粒度 token 被离线缓存成特征库，训练提速 2.9 倍、显存降 1.8 倍。</li><li><strong>部署</strong>：远端 4090 跑模型，机器人异步上传观测、本地规划器执行航点，1600 token 预算下单次推理不超过 0.5 秒。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>BATS 是全文唯一有实质推导的部分。采样概率取</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.188em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϵ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.938em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mopen mtight">(</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mclose mtight">)</span><span class="mord mtight">/</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ϵ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1.</span></span></span></span></span></p><p>它的直觉是「越久远越可能被丢，但永不低于一个地板」。期望采样帧数由积分给出：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">frames</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.5032em;vertical-align:-0.9119em;"></span><span class="mop"><span class="mop op-symbol large-op" style="margin-right:0.4445em;position:relative;top:-0.0011em;">∫</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.5912em;"><span style="top:-1.7881em;margin-left:-0.4445em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span><span style="top:-3.8129em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9119em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.2121em;vertical-align:-0.686em;"></span><span class="mord mathnormal">ϵ</span><span class="mclose">)</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.5261em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">ϵ</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord">.</span></span></span></span></span></p><p>token 预算约束写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mopen">(</span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">frame</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">64</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0502em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">token</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，即每路相机每保留一帧历史耗 5 个 token（4 个粗粒度 + 1 个 TVI），最新一帧额外耗 65 个。于是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">frame</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">5</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0502em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">token</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">65</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord">.</span></span></span></span></span></p><p>代入论文的默认配置可以自行算出两件正文没写的事。其一，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2048</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 时上限是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">2048</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">260</span><span class="mclose">)</span><span class="mord">/20</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">89</span></span></span></span> 帧；而 RxR 的典型 episode 约 122 步，解 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0991em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.70</span></span></span></span> 得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.75</span></span></span></span>，此时最旧一帧的采样概率是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord">0.9</span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">0.75</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.53</span></span></span></span>。<strong>也就是说在论文的主设定下，这条&quot;遗忘曲线&quot;其实相当平缓——最旧与最新之间只差不到两倍</strong>，它与均匀采样的差别远比&quot;指数遗忘&quot;这个名字暗示的要小（这一点是我从公式代入推出的，论文未讨论）。其二，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 时上限降到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">2048</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">390</span><span class="mclose">)</span><span class="mord">/30</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">55</span></span></span></span> 帧，只有四相机的六成，这就为表 13 中&quot;六相机反而略差于四相机&quot;给出了定量解释：多出来的两路视角挤掉了约三分之一的历史容量。</p><p>TVI token 一侧没有推导，只有构造：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">AnglePE</span></span><span class="mopen">(</span><span class="mord mathnormal">ϕ</span><span class="mclose">)</span></span></span></span> 是对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϕ</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϕ</span></span></span></span> 分别做正弦位置编码后拼接，这样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϵ</span><span class="mclose">)</span></span></span></span> 小而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">d</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mclose">)</span></span></span></span> 大，圆周连续性成立；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">TimePE</span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 是对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 的标准正弦编码。三种任务共用同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Base</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，靠加不加两个 MLP 分支来区分。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：统一表述会不会打不过各自领域的专家？</strong> 七个基准的答案是「不会，但也没有全面碾压」。VLN-CE 上，单视角设定 R2R 56.2 SR / RxR 57.4 SR，四视角设定 R2R 61.7 / RxR 64.4，后者超过了使用 RGB-D + 里程计的 HNR（RxR 56.3）。OVON 零样本单视角在 Val-Unseen 上 43.6 SR，高于有监督 SOTA 的 40.8；四视角 45.2。EVT-Bench 单视角 85.0/61.4 SR（单目标/干扰目标）已与专门微调的 TrackVLA（85.1/57.6）持平或更好，四视角 88.4/62.0。NAVSIM 上八视角 PDMS 84.3，与 UniAD 83.4、PARA-Drive 84.0、LAW 84.6 同档，但明显低于用了激光雷达与扩散多模态头的 DiffusionDrive（88.1）。</p><p><strong>问题二：跨任务共训到底带来什么？</strong> 图 12 的答案很戏剧：Searching 从 10.3% 升到 45.2%，Tracking 从 12.6% 升到 62.0%，VLN 与 Driving 也稳定上升。作者自己给出了解释——这两个任务的训练数据是单视角、闭集目标，而评测是多视角、开放词表，共训把「多视角 + 开放目标」的能力从别的任务借了过来。</p><p><strong>问题三：TVI 与 BATS 是不是必要的？</strong> 表 6 是全文信息量最大的表。在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2048</span></span></span></span> 的 RxR 四相机设定下，BATS 64.4 SR / 65.8 nDTW，优于 token merging（63.2/64.4）、均匀采样（62.4/63.9）与线性概率采样（63.0/64.8）；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 从 2048 降到 1024 时 nDTW 只掉 1.4，而均匀采样掉 6.0。token 组织方式一侧，TVI（64.4）远好于传统视角-历史位置编码（52.3）、每个视角一个可学特殊 token（59.1）、以及去掉两个 MLP 的手工 token（53.6）。</p><p><strong>问题四：真机能用吗？</strong> 作者在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mord text"><span class="mord">m</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span><span class="mord text"><span class="mord">m</span></span></span></span></span> 空间里设计了 110 个可复现测试用例（VLN 50、搜索 30、跟踪 30），并在四足、人形、无人机、轮式四种本体上做了定性演示。但<strong>这一节的定量结果只出现在图 10 的柱状图里，正文没有给出任何成功率数值</strong>，故本文不复述真机分数。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：NavFoM 把 VLN、目标搜索、主动跟踪、自动驾驶统一成「多路第一视角视频 + 指令 → 8 个归一化航点」的单一回归问题，在 802 万导航样本 + 476 万 QA 样本上共训一个 epoch。它的两个关键设计是 TVI token（把每个视觉 token 的时刻与方位角显式告诉 LLM）与 BATS（在硬 token 预算下按指数遗忘曲线采样历史帧）。七个基准上不做任务微调即达到 SOTA 或接近 SOTA，其中 RxR 四视角 64.4 SR 超过了用 RGB-D + 里程计的专家方法。消融显示 TVI 相对传统位置编码值 12 个 SR 点，是全文最大的单项贡献。跨任务共训的巨大收益（搜索 +34.9、跟踪 +49.4）主要来自单任务基线被限制在单视角闭集设定，而非纯粹的知识迁移。</p><p><strong>3 句话版</strong>：把导航的多样性归结为「相机配置 + 时间跨度 + 轨迹尺度」三个可参数化的自由度，分别用 TVI token、BATS 采样、任务缩放因子吸收掉，剩下的部分就可以用一个 7B 视频 VLM 端到端学。七个基准零微调达到或接近 SOTA。最大的未解问题是统一的 MSE 航点回归在多模态未来（尤其是驾驶）上会被平均掉。</p><p><strong>1 句话版</strong>：导航基础模型的瓶颈不是视觉编码，而是把「哪个相机、哪一刻」这件事讲清楚。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的一条是：<strong>给定指令与观测，未来轨迹是单峰的，因而可以用 MSE 回归到一个点估计</strong>。NavFoM 的规划头是三层 MLP + MSE，输出 8 个确定性航点，没有任何多模态建模。</p><p>这条假设在室内 VLN 上大体成立——走廊里往目标方向走的合理路径基本唯一。但它在两处会崩。第一处是自动驾驶：路口既可以直行也可以左转，条件分布是双峰的，MSE 的最优解是两条轨迹的算术平均，即一条谁也不服务的中间轨迹。论文自己的 NAVSIM 表格给出了旁证——表中多个基线用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">8192</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 即 8192 个轨迹锚点做分类式规划，DiffusionDrive 用扩散头显式建模多模态并拿到全表最高的 88.1 PDMS，而 NavFoM 的 84.3 恰好落在所有&quot;单点回归&quot;方法的区间内。第二处是探索类任务：在未知房间里，向左探还是向右探往往同样合理。</p><p>论文为这条假设提供的证据是间接的：它证明了统一回归&quot;够用&quot;（各基准接近 SOTA），但从未测量过预测轨迹的多样性，也没有做过&quot;同一观测下真值轨迹分布有多宽&quot;的分析。缺的关键证据是：把规划头换成锚点分类或扩散头、其余全部不变的对照实验。如果换头之后驾驶大涨而室内不变，那统一表述的边界就被定位在了&quot;未来是否单峰&quot;这条线上。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要复现 8M 样本训练的方案：只验证 BATS 相对均匀采样的增益是否真的来自&quot;指数遗忘&quot;这个形状。</p><ul><li><strong>数据与模型</strong>：取任一开源的单目 VLN-CE 视频策略（如公开的 Uni-NaVid / StreamVLN 权重），冻结全部参数，只改推理期的历史帧选取。</li><li><strong>实现</strong>：三个变体，token 预算严格对齐。(a) 均匀采样但<strong>始终保留最新一帧的细粒度 token</strong>；(b) BATS，按论文公式解 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>；(c) 随机均匀伯努利采样（保留期望帧数相同，但概率处处相等且随机）。</li><li><strong>测量</strong>：RxR Val-Unseen 的 SR 与 nDTW，重复 3 个随机种子。</li><li><strong>判据</strong>：若 (b) 显著优于 (a) 且 (c) 介于两者之间，说明增益来自&quot;倾斜&quot;这个形状；若 (b) 与 (c) 无显著差异而两者都优于 (a)，则增益来自<strong>采样的随机性本身</strong>（一种推理期正则），与遗忘曲线无关；若三者都无差异，则表 6 的增益不可迁移，需要重训才能复现。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对全文最亮眼的那张图（图 12 的跨任务共训收益）设计攻击：<strong>&quot;跨任务协同&quot;的绝大部分可能只是&quot;多视角数据增强&quot;的换名。</strong></p><p>论文自己写明了机制——Searching 的训练数据是单相机、闭集类别（来自 L3MVN 采集的 HM3D ObjectNav 成功轨迹），Tracking 的训练数据也只有单视角，而两者的评测都是四视角、开放词表。也就是说，&quot;只用本任务数据&quot;的那个基线在评测配置上是<strong>分布外</strong>的：它从未见过四路相机，也从未见过训练类别之外的目标。把别的任务的数据加进来，最直接的作用是让模型见到了多相机排布与多样目标描述，而不是学到了&quot;搜索与跟踪共享的导航技能&quot;。</p><p>干净的对照是现成的：VLN 数据的采集流程本身就带相机随机化（1–8 路环视、高度 0.6–1.5 米、HFoV 75°–120°）。只要把同一套随机化施加到单任务的 Searching/Tracking 数据上重训，就能把&quot;多视角暴露&quot;与&quot;跨任务知识&quot;分开。论文没有做这个对照。可预测的失败方向是：如果加了随机化的单任务基线就能吃掉大部分的 34.9 与 49.4 个点，那么&quot;跨任务协同&quot;这一条贡献需要大幅降级。</p><p>一个次级但同样有力的替代解释针对 EVT-Bench：作者自己承认该基准的目标&quot;大多生成在机器人正前方&quot;，所以从单视角换到四视角只涨 0.6 点。这说明多视角的价值高度依赖基准是否把信息放在视野之外——四相机在 RxR 上涨 7.0 点、在 EVT 上涨 0.6 点，两者的差距本身就是&quot;基准设计决定收益&quot;的证据。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：BATS 是一条固定的、离线解出的遗忘曲线。它对所有帧一视同仁地只看&quot;多久以前&quot;，完全不看&quot;这一帧里有没有信息&quot;。而导航历史的信息密度极不均匀——转弯前后的几帧、第一次看到目标物体的那一帧，其价值远高于走廊里连续二十帧几乎相同的画面。同样，六相机反而变差说明 token 预算在&quot;视角&quot;与&quot;历史&quot;之间的分配也是写死的。</p><p><strong>(b) 可借鉴的相邻工具</strong>：把 token 预算分配当成一个<strong>可学的、带约束的资源分配策略</strong>，直接对接两条成熟线索——LLM 长上下文里的 KV cache 驱逐（H2O、SnapKV 的注意力得分准则），以及自适应计算（early-exit / mixture-of-depths 的路由器）。关键的改造是：在 LLM 里，驱逐准则只能事后用注意力分数近似；而在导航里，我们有一个真正的下游目标（轨迹 MSE 与任务成功率），因此可以把&quot;保留哪些帧、给哪路相机多少 token&quot;训练成一个以导航损失为奖励的离散策略，用 straight-through 或 REINFORCE 优化。这把 BATS 从超参变成了模型的一部分，也顺带把&quot;六相机反而更差&quot;这个现象变成了可优化的对象。</p><p><strong>(c) 第一个实验长什么样</strong>：固定 NavFoM 的骨干与预算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2048</span></span></span></span>，只在最后一层之前加一个轻量路由器，输入是每帧的粗粒度 token 与其 TVI token，输出保留概率；训练时用 Gumbel-Top-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 做可微选择，损失是原轨迹 MSE 加一项预算惩罚。评测三条曲线：路由器 vs BATS vs 均匀采样在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1024</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2048</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4096</span><span class="mclose">}</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">6</span><span class="mclose">}</span></span></span></span> 的九宫格上的 nDTW。判据是六相机那一格——如果学出来的分配能让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 反超 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>，就说明瓶颈确实在分配策略而非视角冗余；如果依然反超不了，那论文关于&quot;六个相机的观测覆盖并不比四个多多少&quot;的解释才被真正证实。</p>',54)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
